import{_ as a,o as t,c as o,ai as i}from"./chunks/framework.Ci0kozOl.js";const m=JSON.parse('{"title":"Introduction","description":"","frontmatter":{},"headers":[],"relativePath":"3.0/introduction/index.md","filePath":"3.0/introduction/index.md","lastUpdated":1786015710000}'),n={name:"3.0/introduction/index.md"};function r(s,e,l,u,d,c){return t(),o("div",null,[...e[0]||(e[0]=[i('<h1 id="introduction" tabindex="-1">Introduction <a class="header-anchor" href="#introduction" aria-label="Permalink to &quot;Introduction&quot;">​</a></h1><h2 id="unopim-a-powerful-open-source-pim-platform" tabindex="-1">UnoPim: A Powerful Open-Source PIM Platform <a class="header-anchor" href="#unopim-a-powerful-open-source-pim-platform" aria-label="Permalink to &quot;UnoPim: A Powerful Open-Source PIM Platform&quot;">​</a></h2><p>UnoPim is a leading open-source Product Information Management (PIM) platform built on Laravel 13, PHP 8.4, Vue 3, and Tailwind CSS. It offers a comprehensive set of tools to manage product data efficiently across multiple channels and locales. UnoPim is actively developed on <a href="https://github.com/unopim/unopim" target="_blank" rel="noreferrer">GitHub</a>.</p><div class="tip custom-block"><p class="custom-block-title">What&#39;s new in v3.0</p><p>v3.0 introduces Digital Product Passports, configurable association types, advanced product variants, measurement families with unit conversions, Microsoft SSO (Entra ID), multi-webhooks, and a modernized admin with AJAX navigation and dark mode. See <a href="./../api/whats-new-v3.html">What&#39;s New in v3.0</a> for the full list. Upgrading from v2.x? See the <a href="./../prologue/upgrade-guide.html">Upgrade Guide</a>.</p></div><h2 id="key-features-of-unopim" tabindex="-1">Key Features of UnoPim <a class="header-anchor" href="#key-features-of-unopim" aria-label="Permalink to &quot;Key Features of UnoPim&quot;">​</a></h2><p>UnoPim comes with powerful features that empower businesses to manage their product information effectively and distribute it across various sales channels:</p><h3 id="modular-design" tabindex="-1">Modular Design <a class="header-anchor" href="#modular-design" aria-label="Permalink to &quot;Modular Design&quot;">​</a></h3><p>UnoPim&#39;s modular architecture allows for flexibility and customization, making it easy for developers to extend or modify the platform to suit specific business needs. This modularity provides the freedom to build a PIM solution tailored to your enterprise.</p><h3 id="multi-channel-product-distribution" tabindex="-1">Multi-Channel Product Distribution <a class="header-anchor" href="#multi-channel-product-distribution" aria-label="Permalink to &quot;Multi-Channel Product Distribution&quot;">​</a></h3><p>UnoPim simplifies product management by enabling businesses to centralize their product data and distribute it across multiple sales channels, ensuring consistency and accuracy in product information across platforms.</p><h3 id="multi-locale-and-multi-currency-support" tabindex="-1">Multi-Locale and Multi-Currency Support <a class="header-anchor" href="#multi-locale-and-multi-currency-support" aria-label="Permalink to &quot;Multi-Locale and Multi-Currency Support&quot;">​</a></h3><p>UnoPim supports multiple locales and currencies during installation, making it an ideal choice for businesses operating in different regions. This global-ready approach allows for seamless setup in various languages and currencies, enhancing the usability of the PIM solution.</p><h3 id="efficient-product-data-management" tabindex="-1">Efficient Product Data Management <a class="header-anchor" href="#efficient-product-data-management" aria-label="Permalink to &quot;Efficient Product Data Management&quot;">​</a></h3><p>UnoPim streamlines the management of product information, allowing businesses to handle complex data, such as product attributes, descriptions, and categorizations. It provides tools to keep product data consistent and up-to-date, facilitating smooth workflows and collaboration.</p><h3 id="ai-powered-enrichment" tabindex="-1">AI-Powered Enrichment <a class="header-anchor" href="#ai-powered-enrichment" aria-label="Permalink to &quot;AI-Powered Enrichment&quot;">​</a></h3><p>UnoPim 3.0 ships with an integrated AI Agent that exposes 32+ PIM-specific tools through a chat-style interface, plus the <strong>MagicAI</strong> content engine which supports 10+ providers (OpenAI, Gemini, Groq, Ollama, Anthropic, and more) for generation and translation of product attribute values across locales.</p><h3 id="swatch-attributes-and-dashboard-insights" tabindex="-1">Swatch Attributes and Dashboard Insights <a class="header-anchor" href="#swatch-attributes-and-dashboard-insights" aria-label="Permalink to &quot;Swatch Attributes and Dashboard Insights&quot;">​</a></h3><p>Visual swatch types (color, image, text) for product attributes enable richer catalog experiences. The redesigned dashboard surfaces channel readiness, product trend charts, and recent activity in a single view.</p><h2 id="community-and-support" tabindex="-1">Community and Support <a class="header-anchor" href="#community-and-support" aria-label="Permalink to &quot;Community and Support&quot;">​</a></h2><p>UnoPim benefits from a vibrant community of developers and contributors, offering support and enhancements to the platform.</p><ul><li><p><strong>Explore UnoPim</strong>: Learn more about UnoPim at <a href="https://unopim.com" target="_blank" rel="noreferrer">https://unopim.com</a> and experience a demo of its features.</p></li><li><p><strong>Stay Updated</strong>: Follow the <a href="https://unopim.com/roadmap/" target="_blank" rel="noreferrer">UnoPim roadmap</a> to stay informed about new features and updates.</p></li><li><p><strong>GitHub Repository</strong>: Access the UnoPim repository on <a href="https://github.com/unopim/unopim" target="_blank" rel="noreferrer">GitHub</a>, where the platform is actively developed and maintained.</p></li></ul><p>Join the UnoPim community to streamline your product information management and improve the efficiency of your business operations.</p>',22)])])}const h=a(n,[["render",r]]);export{m as __pageData,h as default};
